  "fha_tbl_ins": "Seguro hipotecario",
  "fha_tbl_ins_fha": "MIP — normalmente por toda la vida del préstamo",
  "fha_tbl_ins_con": "PMI — desaparece con el 20% de patrimonio",
  "fha_tbl_limits": "Límites de préstamo",
  "fha_tbl_limits_fha": "Hasta 766.550 $ (2026)",
  "fha_tbl_limits_con": "Hasta 766.550 $ (2026)",
