  "fvc_results_title": "Resultados",
  "fvc_out_monthly": "Pago Mensual (C + I)",
  "fvc_out_finance_total": "Total Pagado con Financiamiento",
  "fvc_out_cash_total": "Total Pagado en Efectivo",
